<template>
  <div class="container">
    <router-link to="/mychannels" class="back-btn">←</router-link>

    <div class="channel-header">
      <h1 class="channel-title">{{ group.username }}</h1>
      <div class="channel-info-grid">
        <div class="info-card">
          <div class="info-number">{{ group.subscribers }}</div>
          <div class="info-label">Подписчики</div>
        </div>
        <div class="info-card">
          <div class="info-number">{{ group.avg_views }}</div>
          <div class="info-label">Просмотры</div>
        </div>
      </div>
      <!-- Секция выбора типа рекламы и цены -->
      <div class="ad-type-section" v-if="adTypes.length">
        <label for="adTypeSelect">Тип рекламы:</label>
        <select id="adTypeSelect" v-model="selectedAdType">
          <option 
            v-for="type in adTypes" 
            :key="type.id" 
            :value="type.id"
          >
            {{ type.duration_in_hours }}/{{ type.top_duration_in_hours }}
          </option>
        </select>
        <label for="adPriceInput">Цена (₽):</label>
        <input 
          id="adPriceInput" 
          type="number" 
          v-model.number="adPrice" 
          min="0" 
        />
      </div>
      <div class="channel-actions">
        <button class="action-btn secondary" @click="editGroup">
          Сохранить изменения
        </button>
        <button class="action-btn primary" @click="toggleCatalog">
          {{ inCatalog ? 'Убрать из каталога' : 'Добавить в каталог' }}
        </button>
      </div>
    </div>

    <div class="schedule-section">
      <div class="schedule-title">Расписание публикаций</div>
      <div class="schedule-grid">
        <div class="schedule-time-header"></div>
        <div
          v-for="(day, idx) in days"
          :key="idx"
          class="schedule-day-header"
        >
          {{ day }}
        </div>
        <template v-for="hour in hours" :key="hour">
          <div class="schedule-time-label">{{ hour }}</div>
          <div
            v-for="(day, dIdx) in days"
            :key="dIdx + '-' + hour"
            class="schedule-cell"
            :class="{ active: isActive(dIdx, hour) }"
            @click="toggleCell(dIdx, hour)"
          ></div>
        </template>
      </div>
      <button
        class="action-btn primary"
        @click="saveSchedule"
        style="margin-top: 16px;"
      >
        Сохранить расписание
      </button>
    </div>
  </div>
</template>

<script setup>
import { ref, reactive, onMounted } from 'vue'
import { useAppStore } from '@/stores/app'
import { useRoute } from 'vue-router'

const appStore = useAppStore()
const route = useRoute()
const groupId = Number(route.params.id)

const group = reactive({
  username: '',
  subscribers: 0,
  avg_views: 0,
  all_slots: []   // [[dayIdx, hour], ...]
})

const inCatalog = ref(false)

// типы рекламы из справочника
const adTypes = ref([])
const selectedAdType = ref(null)
const adPrice = ref(0)

// дни и часы
const days = ['Пн','Вт','Ср','Чт','Пт','Сб','Вс']
const hours = Array.from({ length: 24 }, (_, i) => i)

// активные слоты
const activeSlots = ref(new Set())

const headers = () => ({
  'Content-Type': 'application/json',
  Authorization: 'Telegram-Init-Data ' + appStore.tgInitDataRow
})

function isActive(dIdx, hour) {
  const rawDay = dIdx + 1
  return activeSlots.value.has(`${rawDay}-${hour}`)
}
function toggleCell(dIdx, hour) {
  const rawDay = dIdx + 1
  const key = `${rawDay}-${hour}`
  if (activeSlots.value.has(key)) activeSlots.value.delete(key)
  else activeSlots.value.add(key)
}

async function saveSchedule() {
  const slots = Array.from(activeSlots.value).map(key => {
    const [day, hour] = key.split('-').map(Number)
    return [day, hour]
  })
  await fetch(
    `${appStore.apiBaseUrl}/api/my/group/${groupId}/schedule`,
    {
      method: 'POST',
      headers: headers(),
      body: JSON.stringify({ slots }),
      mode: 'cors'
    }
  )
  alert('Расписание сохранено')
}

async function editGroup() {
  // собираем объект ad_prices с одним элементом
  const prices = {}
  prices[selectedAdType.value] = adPrice.value

  try {
    await fetch(
      `${appStore.apiBaseUrl}/api/my/group/${groupId}/edit`,
      {
        method: 'POST',
        headers: headers(),
        body: JSON.stringify({
          subject_ids: group.subject_ids || [],
          country_id: group.country_id,
          language_id: group.language_id,
          ad_prices: prices
        }),
        mode: 'cors'
      }
    )
    alert('Изменения сохранены')
  } catch (e) {
    console.error('Ошибка сохранения группы:', e)
  }
}

async function toggleCatalog() {
  inCatalog.value = !inCatalog.value
  await fetch(
    `${appStore.apiBaseUrl}/api/my/group/${groupId}/set_in_catalog`,
    {
      method: 'POST',
      headers: headers(),
      body: JSON.stringify({ in_catalog: inCatalog.value }),
      mode: 'cors'
    }
  )
}

onMounted(async () => {
  await appStore.initTelegram()

  // загружаем справочник типов рекламы
  const resTypes = await fetch(
    `${appStore.apiBaseUrl}/api/tables/ad_types`,
    { headers: headers(), mode: 'cors' }
  )
  adTypes.value = await resTypes.json()

  // загружаем данные группы
  const res = await fetch(
    `${appStore.apiBaseUrl}/api/group/${groupId}`,
    { headers: headers(), mode: 'cors' }
  )
  const data = await res.json()
  Object.assign(group, data)
  inCatalog.value = !!data.in_catalog

  // инициализируем activeSlots
  data.all_slots?.forEach(([dayIdx, hour]) => {
    activeSlots.value.add(`${dayIdx}-${hour}`)
  })

  // выставляем начальный тип и цену, если есть
  const firstTypeId = data.ad_prices ? Object.keys(data.ad_prices)[0] : null
  if (firstTypeId) {
    selectedAdType.value = Number(firstTypeId)
    adPrice.value = data.ad_prices[firstTypeId]
  }
})
</script>

<style>
.schedule-grid {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 2px;
}
.schedule-day-header {
  font-weight: bold;
  text-align: center;
}
.schedule-time-label {
  text-align: right;
  padding-right: 4px;
}
.schedule-cell {
  background: #f0f0f0;
  width: 100%;
  padding-top: 100%;
  cursor: pointer;
}
.schedule-cell.active {
  background: #c6f6d5;
}
/* Доп. стили для секции выбора типа рекламы */
.ad-type-section {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 16px 0;
}
.ad-type-section label {
  font-weight: bold;
}
</style>
